import{c as t,Q as n,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Bundled Premium Plugin Activation","description":"","frontmatter":{},"headers":[],"relativePath":"general/bundled-plugin-activation.md","filePath":"general/bundled-plugin-activation.md"}'),a={name:"general/bundled-plugin-activation.md"};function i(l,e,s,d,u,c){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="bundled-premium-plugin-activation" tabindex="-1">Bundled Premium Plugin Activation <a class="header-anchor" href="#bundled-premium-plugin-activation" aria-label="Permalink to &quot;Bundled Premium Plugin Activation&quot;">​</a></h1><p>Most of our themes include premium plugins such as <a href="http://codecanyon.net/item/visual-composer-page-builder-for-wordpress/242431?ref=wolf-themes" target="_blank" rel="noreferrer">WPBakery Page Builder</a> or <a href="http://codecanyon.net/item/slider-revolution-responsive-wordpress-plugin/2751380?ref=wolf-themes" target="_blank" rel="noreferrer">Slider Revolution</a>.</p><p><strong>You don&#39;t have to activate them</strong> — they will work regardless.</p><p>Some plugins may ask for a purchase code for registration once installed. You can simply <strong>ignore these messages</strong> as bundled plugins <strong>do not</strong> require activation or registration.</p><p>Any time a plugin is updated, you will find the latest version in the <code>includes/admin/plugins</code> or <code>config/plugins</code> folder of the theme.</p><p>For more information, see the official Envato documentation: <a href="https://help.market.envato.com/hc/en-us/articles/213762463-Bundled-Plugins" target="_blank" rel="noreferrer">help.market.envato.com — Bundled Plugins</a></p>',6)])])}const g=t(a,[["render",i]]);export{m as __pageData,g as default};
